import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Lumberjacking","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/lumberjacking.md","filePath":"es/game-design/professions/lumberjacking.md"}'),s={name:"es/game-design/professions/lumberjacking.md"};function r(l,e,t,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="lumberjacking" tabindex="-1">Lumberjacking <a class="header-anchor" href="#lumberjacking" aria-label="Enlace permanente a &quot;Lumberjacking&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y caminos técnicos siguientes siguen siendo candidatos. <strong>Implementación:</strong> este lote documental no establece ninguna implementación del rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de juego. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Lumberjacking debería ser conocimiento forestal/de recursos, además de «golpear un árbol para obtener troncos».</p><h3 id="tree-state" tabindex="-1">Estado del árbol <a class="header-anchor" href="#tree-state" aria-label="Enlace permanente a &quot;Estado del árbol&quot;">​</a></h3><ul><li>especie;</li><li>madurez;</li><li>estado;</li><li>cantidad de recursos;</li></ul><p>con otros comportamientos derivados, en lugar de persistirlos por completo.</p><p>La tala debería alterar físicamente el mundo. Un árbol talado puede ocupar varias casillas y bloquear/alterar temporalmente el tránsito.</p><h3 id="world-and-tactical-utility" tabindex="-1">Utilidad en el mundo y táctica <a class="header-anchor" href="#world-and-tactical-utility" aria-label="Enlace permanente a &quot;Utilidad en el mundo y táctica&quot;">​</a></h3><ul><li>usar árboles talados para bloquear rutas/pasos estrechos;</li><li>utilidad en batalla o asedio;</li><li>posibles puentes improvisados en situaciones específicas;</li><li>interacción con estructuras/terreno mediante reglas simplificadas por casillas.</li></ul><p>No exigir una simulación física completa. El diseño puede asumir una resolución de caída discreta/por casillas.</p><h3 id="tree-knowledge" tabindex="-1">Conocimiento de árboles <a class="header-anchor" href="#tree-knowledge" aria-label="Enlace permanente a &quot;Conocimiento de árboles&quot;">​</a></h3><ul><li>especie;</li><li>madurez;</li><li>salud/enfermedad;</li><li>calidad aproximada de madera;</li><li>ecología regional.</li></ul><h3 id="potential-felling-approaches" tabindex="-1">Posibles enfoques de tala <a class="header-anchor" href="#potential-felling-approaches" aria-label="Enlace permanente a &quot;Posibles enfoques de tala&quot;">​</a></h3><ul><li>tala rápida;</li><li>tala controlada;</li><li>corte selectivo.</li></ul><p>La selección debe tener valor económico/temporal tangible; de lo contrario, los jugadores simplemente talarán todo.</p><h3 id="value-of-knowledge" tabindex="-1">Valor del conocimiento <a class="header-anchor" href="#value-of-knowledge" aria-label="Enlace permanente a &quot;Valor del conocimiento&quot;">​</a></h3><ul><li>mejor rendimiento/tiempo;</li><li>mejor selección de materiales;</li><li>menor desgaste de herramientas;</li><li>mejor recuperación de madera útil;</li><li>evitar árboles enfermos/pobres de escaso valor.</li></ul><p>La regeneración/sobreexplotación regional puede importar, pero la simulación exacta del mundo vivo sigue siendo técnica/propuesta.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Forester&#39;s Journal.</strong> Especies, madurez, salud/enfermedad, calidad aproximada de madera y ecología regional son conocimientos que se aprenden. La tala controlada y el corte selectivo deberían tener valor económico/temporal.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define la enseñanza y la dirección de límites/aumentos. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, intercambio de conocimiento, maestría manual, producción por lotes, encargos y reputación multidimensional. Aquí no se redefinen esas reglas de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define el rango compartido de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en expediciones <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en expediciones&quot;">​</a></h2><p>Carpentry utiliza madera seleccionada; Camping y Cooking pueden usar conocimiento de combustible. Tracking puede interpretar terreno alterado, mientras las reglas del mundo/materiales delimitan silvicultura, fuego y recuperación.</p><p><a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/es/game-design/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/es/game-design/living-world.html#knowledge-professions-and-traces">Camping y Tracking</a> · <a href="/Syrolands-Public/es/game-design/living-world.html#trees-and-forestry">Árboles y silvicultura</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar únicamente estados y respuestas que sustenten decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Nada de esto selecciona ID de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Dirección de caída, espacio ocupado, peligros y propiedad; duración de bloqueos de rutas y espacios protegidos; cuándo se permiten puentes; incentivos de corte selectivo; recuperación regional y sobreexplotación. El candidato posterior de habilidad Forestry no es automáticamente una nueva habilidad junto a esta dirección de Lumberjacking.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y evidencias existentes de combate no validan este rediseño profesional.</p>',32)])])}const g=a(s,[["render",r]]);export{m as __pageData,g as default};
